"""
Command-line entry point for pytoolbox.
"""

import argparse
import json
import sys
from typing import Any, Dict, List, Optional

from . import tasks, validation
from .validation import (
    BooleanValidator,
    DateTimeValidator,
    DictValidator,
    EmailValidator,
    FloatValidator,
    IntegerValidator,
    ListValidator,
    SchemaValidator,
    StringValidator,
    ValidationError,
)


def parse_validator(spec: str) -> 'FieldValidator':
    """
    Parse a validator specification string into a validator object.

    Format: type:options
    Examples:
        - "str:min=2,max=50"
        - "int:min=0,max=150"
        - "float:min=0.0"
        - "bool"
        - "email"
        - "list[str]"
        - "list[str,min_items=2]"
        - "dict[str,str]"
    """
    # Handle list types
    if spec.startswith('list['):
        inner = spec[5:-1]
        if ',' in inner:
            inner_spec, options = inner.split(',', 1)
            validator = parse_validator(inner_spec)
            options_dict = parse_options(options)
            return ListValidator(
                item_validator=validator,
                required=options_dict.get('required', True),
                min_items=options_dict.get('min_items'),
                max_items=options_dict.get('max_items'),
            )
        return ListValidator(item_validator=parse_validator(inner))

    # Handle dict types
    if spec.startswith('dict['):
        inner = spec[5:-1]
        if ',' in inner:
            key_spec, val_spec = inner.split(',', 1)
            return DictValidator(
                key_validator=parse_validator(key_spec),
                value_validator=parse_validator(val_spec),
            )

    # Parse base types
    base_type = spec
    options = {}
    if ':' in spec:
        base_type, options_str = spec.split(':', 1)
        options = parse_options(options_str)

    required = options.pop('required', True)

    if base_type == 'str':
        return StringValidator(required=required, **options)
    elif base_type == 'int':
        return IntegerValidator(required=required, **options)
    elif base_type == 'float':
        return FloatValidator(required=required, **options)
    elif base_type == 'bool':
        return BooleanValidator(required=required)
    elif base_type == 'email':
        return EmailValidator(required=required)
    elif base_type == 'datetime':
        return DateTimeValidator(required=required, **options)
    else:
        raise ValueError(f"Unknown validator type: {base_type}")


def parse_options(options_str: str) -> Dict[str, Any]:
    """Parse comma-separated options into a dictionary."""
    options = {}
    for opt in options_str.split(','):
        if '=' in opt:
            key, value = opt.split('=', 1)
            try:
                options[key] = int(value)
            except (ValueError, TypeError):
                try:
                    options[key] = float(value)
                except (ValueError, TypeError):
                    options[key] = value
        else:
            options[opt] = True
    return options


def cmd_validate(args: argparse.Namespace) -> int:
    """
    Validate a JSON request body against a schema.

    Example:
        echo '{"name": "John", "age": 30}' | toolbox validate 'name:str:min=2' 'age:int:min=0'
    """
    body = None
    if args.input:
        with open(args.input, 'r') as f:
            body = json.load(f)
    else:
        body = json.load(sys.stdin)

    # Parse validators from args
    validators = {}
    for spec in args.validators:
        if ':' in spec:
            field, validator_spec = spec.split(':', 1)
            validators[field] = parse_validator(validator_spec)
        else:
            validators[spec] = StringValidator()

    try:
        result = validation.validate_request_body(body, validators)
    except ValidationError as e:
        if args.verbose:
            print(json.dumps(e.errors, indent=2), file=sys.stderr)
        else:
            print(f"Validation failed: {json.dumps(e.errors)}", file=sys.stderr)
        return 1

    if args.pretty:
        print(json.dumps(result, indent=2, default=str))
    else:
        print(json.dumps(result, default=str))

    return 0


def cmd_schema(args: argparse.Namespace) -> int:
    """
    Generate and print a JSON schema for validation.

    Example:
        toolbox schema 'name:str:min=2,max=50' 'age:int:min=0,max=150' 'email:email'
    """
    schema = {}
    for spec in args.fields:
        if ':' in spec:
            field, validator_spec = spec.split(':', 1)
            validator = parse_validator(validator_spec)
            schema[field] = {
                'type': type(validator).__name__,
                'required': validator.required,
                'default': validator.default if hasattr(validator, 'default') else None,
            }

            if hasattr(validator, 'min_length'):
                schema[field]['min_length'] = validator.min_length
            if hasattr(validator, 'max_length'):
                schema[field]['max_length'] = validator.max_length
            if hasattr(validator, 'min_value'):
                schema[field]['min_value'] = validator.min_value
            if hasattr(validator, 'max_value'):
                schema[field]['max_value'] = validator.max_value
        else:
            schema[spec] = {'type': 'StringValidator', 'required': True}

    print(json.dumps(schema, indent=2))
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(
        prog='toolbox',
        description='Internal Python toolbox CLI for small chores.',
    )
    subparsers = parser.add_subparsers(dest='command', help='Available commands')

    # Validate command
    validate_parser = subparsers.add_parser(
        'validate',
        help='Validate a JSON request body against a schema',
    )
    validate_parser.add_argument(
        '-i', '--input',
        help='Input file containing JSON (default: stdin)',
    )
    validate_parser.add_argument(
        '-p', '--pretty',
        action='store_true',
        help='Pretty-print the output',
    )
    validate_parser.add_argument(
        '-v', '--verbose',
        action='store_true',
        help='Show detailed error information',
    )
    validate_parser.add_argument(
        'validators',
        nargs='+',
        help='Field validators (field:type:options)',
    )
    validate_parser.set_defaults(func=cmd_validate)

    # Schema command
    schema_parser = subparsers.add_parser(
        'schema',
        help='Generate a JSON schema for field specifications',
    )
    schema_parser.add_argument(
        '--pretty',
        action='store_true',
        help='Pretty-print the output',
    )
    schema_parser.add_argument(
        'fields',
        nargs='+',
        help='Field specifications (field:type:options)',
    )
    schema_parser.set_defaults(func=cmd_schema)

    args = parser.parse_args()

    if not args.command:
        parser.print_help()
        return 0

    return args.func(args)


if __name__ == '__main__':
    sys.exit(main())

