"""
Shared utilities for pytoolbox.
"""

import json
import re
from typing import Any, Dict, List, Optional, Tuple, Union


def is_valid_json(data: Union[str, bytes, bytearray]) -> bool:
    """Check if a string is valid JSON."""
    try:
        json.loads(data)
        return True
    except (ValueError, TypeError):
        return False


def parse_json_array(json_str: str) -> List[Any]:
    """Parse a JSON array string, raising a descriptive error on failure."""
    try:
        result = json.loads(json_str)
        if not isinstance(result, list):
            raise ValueError(f"Expected JSON array, got {type(result).__name__}")
        return result
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON: {e}")


def str_to_bool(value: str) -> bool:
    """Convert a string representation to boolean."""
    if isinstance(value, bool):
        return value

    normalized = value.strip().lower()
    if normalized in ('true', 'yes', '1', 'on', 'y', 't'):
        return True
    if normalized in ('false', 'no', '0', 'off', 'n', 'f'):
        return False

    raise ValueError(f"Cannot convert {value!r} to boolean")


def type_name(value: Any) -> str:
    """Get a friendly type name for a value."""
    return type(value).__name__


def read_stdin() -> str:
    """Read all content from stdin."""
    import sys
    return sys.stdin.read()


def read_json_from_stdin() -> Dict[str, Any]:
    """Read and parse JSON from stdin."""
    data = read_stdin()
    if not is_valid_json(data):
        raise ValueError("Invalid JSON in stdin")
    return json.loads(data)

def print_table(records, headers=None, max_width=None, alignment=None):
    """
    Print a list of records as an aligned table.

    Args:
        records: List of records (each can be a dict, list, or tuple)
        headers: Optional header names. If None, uses record keys (for dicts) 
                or column numbers (for lists)
        max_width: Maximum width for each column (default: None = no limit)
        alignment: Dict mapping column index to alignment ('left', 'right', 'center')
                  Default: all left-aligned except numeric columns (right-aligned)
    """
    if not records:
        print("(No records to display)")
        return

    # Convert records to list of lists
    if isinstance(records[0], dict):
        if not headers:
            headers = list(records[0].keys())
        rows = [[str(rec.get(h, '')) for h in headers] for rec in records]
    else:
        if not headers:
            headers = [f"Col {i+1}" for i in range(len(records[0]))]
        rows = [[str(cell) for cell in record] for record in records]

    # Ensure all rows have same number of columns
    num_cols = len(headers)
    rows = [row + [''] * (num_cols - len(row)) for row in rows]

    # Calculate column widths
    col_widths = []
    for i in range(num_cols):
        # Consider header and all values
        values = [headers[i]] + [row[i] for row in rows]
        if max_width:
            # Truncate values if needed
            values = [v[:max_width] + '...' if len(v) > max_width else v 
                     for v in values]
        width = max(len(v) for v in values)
        col_widths.append(width)

    # Default alignment: right-align numeric columns, left-align everything else
    if not alignment:
        alignment = {}
        for i in range(num_cols):
            try:
                # Check if column contains mostly numbers
                numeric_count = sum(1 for row in rows if row[i].replace('-', '').replace('.', '').isdigit())
                if numeric_count > len(rows) * 0.8:
                    alignment[i] = 'right'
                else:
                    alignment[i] = 'left'
            except:
                alignment[i] = 'left'

    # Format and print the table
    separator = '+' + '+'.join('-' * (w + 2) for w in col_widths) + '+'

    # Print header
    print(separator)
    header_cells = []
    for i, header in enumerate(headers):
        align = alignment.get(i, 'left')
        if align == 'right':
            header_cells.append(f" {header:>{col_widths[i]}} ")
        elif align == 'center':
            header_cells.append(f" {header:^{col_widths[i]}} ")
        else:
            header_cells.append(f" {header:<{col_widths[i]}} ")
    print('|' + '|'.join(header_cells) + '|')
    print(separator)

    # Print data rows
    for row in rows:
        cells = []
        for i, cell in enumerate(row):
            # Truncate if needed
            if max_width and len(cell) > max_width:
                cell = cell[:max_width] + '...'

            align = alignment.get(i, 'left')
            if align == 'right':
                cells.append(f" {cell:>{col_widths[i]}} ")
            elif align == 'center':
                cells.append(f" {cell:^{col_widths[i]}} ")
            else:
                cells.append(f" {cell:<{col_widths[i]}} ")
        print('|' + '|'.join(cells) + '|')

    print(separator)
    print(f"\nTotal: {len(rows)} record(s)")

records = [
    {"name": "Alice", "age": 30, "city": "New York"},
    {"name": "Bob", "age": 25, "city": "San Francisco"},
    {"name": "Charlie", "age": 35, "city": "Chicago"}
]
print_table(records)

import os
from pathlib import Path
from typing import Any, Optional
import json

def get_env_value(
    key: str,
    default: Any = None,
    env_file: str = ".env",
    convert_types: bool = True
) -> Any:
    """
    Read a value from .env file with type conversion support.
    """
    value = None
    found = False

    # Check system environment first
    if key in os.environ:
        value = os.environ[key]
        found = True

    # Check .env file
    if not found:
        env_path = Path(env_file)
        if env_path.exists():
            with open(env_path, 'r') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#') or '=' not in line:
                        continue

                    env_key, env_value = line.split('=', 1)
                    env_key = env_key.strip().strip('"').strip("'")

                    if env_key == key:
                        value = env_value.strip().strip('"').strip("'")
                        found = True
                        break

    if not found:
        return default

    # Optional type conversion
    if convert_types:
        # Try to convert to boolean
        if value.lower() in ('true', 'false', '1', '0'):
            return value.lower() in ('true', '1')

        # Try to convert to number
        try:
            return int(value)
        except ValueError:
            try:
                return float(value)
            except ValueError:
                pass

        # Try to convert to JSON/object
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            pass

    return value

"""Shared utilities for the toolbox package."""

import json
import sys
from pathlib import Path
from typing import Any, Dict, List, Optional


def read_file(path: str) -> str:
    """Read a file and return its contents."""
    file_path = Path(path)
    if not file_path.exists():
        raise FileNotFoundError(f"File not found: {path}")
    if not file_path.is_file():
        raise ValueError(f"Not a file: {path}")
    return file_path.read_text(encoding="utf-8")


def write_file(path: str, content: str) -> None:
    """Write content to a file."""
    file_path = Path(path)
    file_path.parent.mkdir(parents=True, exist_ok=True)
    file_path.write_text(content, encoding="utf-8")


def parse_json_file(path: str) -> Any:
    """Parse a JSON file and return the data."""
    content = read_file(path)
    try:
        return json.loads(content)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in {path}: {e}")


def write_json_file(path: str, data: Any) -> None:
    """Write data as JSON to a file."""
    content = json.dumps(data, indent=2, ensure_ascii=False)
    write_file(path, content)


def print_success(message: str) -> None:
    """Print a success message in green."""
    print(f"\033[92m✓ {message}\033[0m")


def print_error(message: str) -> None:
    """Print an error message in red."""
    print(f"\033[91m✗ {message}\033[0m", file=sys.stderr)


def print_warning(message: str) -> None:
    """Print a warning message in yellow."""
    print(f"\033[93m⚠ {message}\033[0m")


def format_number(number: float) -> str:
    """Format a number with thousands separators."""
    return f"{number:,}"


def validate_country_code(country: str) -> bool:
    """Validate a country code or name."""
    import phonenumbers
    try:
        phonenumbers.region_code_for_country_code(country)
        return True
    except Exception:
        return False

