def format_phone_number(args: argparse.Namespace) -> int:
    """
    Validate and format a phone number into international format.

    Examples:
        toolbox phone "020 7198 4321" --country GB
        toolbox phone --input contacts.csv --country US --column phone
    """
    input_value = args.number
    country = args.country.upper()

    # Validate country code
    try:
        phonenumbers.country_code_for_region(country)
    except Exception:
        print_error(f"Invalid country code: {country}")
        return 1

    # Process input
    if args.input:
        return _process_batch(args.input, country, args.column, args.output)

    if not input_value:
        print_error("No phone number provided. Use --number or --input.")
        return 1

    result = _format_single_number(input_value, country, args.format)

    if result:
        print(result)
        return 0
    return 1


def _format_single_number(
    number: str,
    country: str,
    format_type: str,
) -> Optional[str]:
    """Format a single phone number."""
    try:
        # Parse the number
        parsed = phonenumbers.parse(number, country)

        # Check if it's a valid number
        if not phonenumbers.is_valid_number(parsed):
            # Check if it's possible (might just be missing area code)
            if phonenumbers.is_possible_number(parsed):
                print_warning(
                    f"Number {number} is possible but not valid for {country}."
                )
                print_warning("Adding country prefix...")
                # Try to fix by adding country code
                try:
                    parsed = phonenumbers.parse(
                        f"+{phonenumbers.country_code_for_region(country)}"
                        f" {number.lstrip('0')}",
                        None,
                    )
                except Exception:
                    return None
            else:
                print_error(f"Invalid phone number: {number}")
                return None

        # Format the number
        if format_type == "e164":
            formatted = phonenumbers.format_number(
                parsed, phonenumbers.PhoneNumberFormat.E164
            )
        elif format_type == "international":
            formatted = phonenumbers.format_number(
                parsed, phonenumbers.PhoneNumberFormat.INTERNATIONAL
            )
        elif format_type == "national":
            formatted = phonenumbers.format_number(
                parsed, phonenumbers.PhoneNumberFormat.NATIONAL
            )
        elif format_type == "rfc3966":
            formatted = phonenumbers.format_number(
                parsed, phonenumbers.PhoneNumberFormat.RFC3966
            )
        else:
            print_error(f"Unknown format type: {format_type}")
            return None

        return formatted

    except phonenumbers.phonenumberutil.NumberParseException as e:
        print_error(f"Error parsing number '{number}': {e}")
        return None
    except Exception as e:
        print_error(f"Unexpected error processing '{number}': {e}")
        return None


def _process_batch(
    input_file: str,
    country: str,
    column: Optional[str],
    output_file: Optional[str],
) -> int:
    """Process multiple phone numbers from a file."""
    try:
        content = read_file(input_file)
    except FileNotFoundError as e:
        print_error(str(e))
        return 1

    # Determine file format
    if input_file.endswith('.csv'):
        return _process_csv(content, country, column, output_file)
    elif input_file.endswith('.json'):
        return _process_json(content, country, column, output_file)
    elif input_file.endswith('.txt'):
        return _process_txt(content, country, output_file)
    else:
        print_error(f"Unsupported file format: {input_file}")
        return 1


def _process_csv(
    content: str,
    country: str,
    column: Optional[str],
    output_file: Optional[str],
) -> int:
    """Process CSV file."""
    import csv
    import io

    successes = 0
    failures = 0
    results = []
    errors = []

    csv_reader = csv.DictReader(io.StringIO(content))

    # If no column specified, try to find phone column
    if not column:
        possible_columns = ['phone', 'phonenumber', 'phone_number', 'number', 'tel', 'telephone']
        col_names = csv_reader.fieldnames or []
        column = next((col for col in possible_columns if col in col_names), None)
        if not column:
            print_error("Could not determine phone column. Use --column to specify.")
            return 1

    if column not in (csv_reader.fieldnames or []):
        print_error(f"Column '{column}' not found in CSV file.")
        print_error(f"Available columns: {', '.join(csv_reader.fieldnames or [])}")
        return 1

    for i, row in enumerate(csv_reader, 2):
        phone = row.get(column, '').strip()
        if not phone:
            continue

        original_row = dict(row)

        if phone:
            formatted = _format_single_number(phone, country, "international")
            if formatted:
                row[column] = formatted
                successes += 1
                results.append(row)
            else:
                failures += 1
                errors.append(f"Row {i}: Invalid phone '{phone}'")
                if args_keep_invalid():
                    results.append(original_row)

    # Write results
    if output_file:
        fieldnames = csv_reader.fieldnames
        with open(output_file, 'w', newline='', encoding='utf-8') as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames)
            writer.writeheader()
            writer.writerows(results)
        print_success(f"Processed {successes} numbers successfully, {failures} failed.")
        print_success(f"Results written to {output_file}")
    else:
        # Print to stdout
        for row in results:
            print(','.join(str(row.get(field, '')) for field in csv_reader.fieldnames))

    if errors:
        print_warning(f"Errors ({len(errors)}):")
        for error in errors[:10]:  # Show first 10 errors
            print_warning(f"  {error}")

    return 0 if failures == 0 else 1


def _process_json(
    content: str,
    country: str,
    column: Optional[str],
    output_file: Optional[str],
) -> int:
    """Process JSON file."""
    import json

    try:
        data = json.loads(content)
    except json.JSONDecodeError as e:
        print_error(f"Invalid JSON: {e}")
        return 1

    success = 0
    failures = 0

    def process_item(item):
        nonlocal success, failures

        if isinstance(item, dict):
            # Find phone field
            phone_col = column or next(
                (k for k in item if 'phone' in k.lower() or 'number' in k.lower()),
                None
            )
            if phone_col and phone_col in item:
                phone = item[phone_col]
                if isinstance(phone, str) and phone.strip():
                    formatted = _format_single_number(phone.strip(), country, "international")
                    if formatted:
                        item[phone_col] = formatted
                        success += 1
                    else:
                        failures += 1
            for value in item.values():
                if isinstance(value, (dict, list)):
                    process_item(value)
        elif isinstance(item, list):
            for sub_item in item:
                process_item(sub_item)

    process_item(data)

    if output_file:
        import json
        with open(output_file, 'w', encoding='utf-8') as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        print_success(f"Processed {success} numbers successfully, {failures} failed.")
        print_success(f"Results written to {output_file}")
    else:
        print(json.dumps(data, indent=2, ensure_ascii=False))

    return 0 if failures == 0 else 1


def _process_txt(
    content: str,
    country: str,
    output_file: Optional[str],
) -> int:
    """Process text file (one number per line)."""
    lines = content.strip().split('\n')
    success = 0
    failures = 0
    results = []
    errors = []

    for i, line in enumerate(lines, 1):
        line = line.strip()
        if not line:
            continue

        formatted = _format_single_number(line, country, "international")
        if formatted:
            results.append(formatted)
            success += 1
        else:
            failures += 1
            errors.append(f"Line {i}: '{line}'")

    output = '\n'.join(results)

    if output_file:
        write_file(output_file, output + '\n')
        print_success(f"Processed {success} numbers successfully, {failures} failed.")
        print_success(f"Results written to {output_file}")
    else:
        print(output)

    if errors:
        print_warning(f"Failed numbers ({len(errors)}):")
        for error in errors:
            print_warning(f"  {error}")

    return 0 if failures == 0 else 1


def args_keep_invalid() -> bool:
    """Check if we should keep invalid numbers."""
    # This would be set via a flag in the CLI
    return True

