def is_valid_url(url: str) -> bool:
    """Simple URL validation."""
    return url.startswith(("http://", "https://"))


def format_bytes(size_bytes: int) -> str:
    """Format bytes into human readable size."""
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if size_bytes < 1024.0:
            return f"{size_bytes:.1f} {unit}"
        size_bytes /= 1024.0
    return f"{size_bytes:.1f} PB"

import os

def get_env_value(key, default=None, env_file='.env'):
    """Simple version to read .env file and return value with default."""
    if key in os.environ:
        return os.environ[key]

    try:
        with open(env_file) as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#') and key in line.split('=')[0]:
                    return line.split('=', 1)[1].strip().strip('"\'')
    except FileNotFoundError:
        pass

    return default

from dataclasses import dataclass, field
from typing import Optional, Literal
from datetime import datetime
import json


@dataclass(frozen=True)
class UserInput:
    """Typed model for user input validation."""
    name: str
    email: str
    age: int
    role: Literal["admin", "user", "guest"]
    is_active: bool = True
    created_at: datetime = field(default_factory=datetime.now)
    nickname: Optional[str] = None


def validate_user_data(data: dict) -> UserInput:
    """Validate and parse request body into UserInput model."""

    # Check required fields
    required_fields = ["name", "email", "age", "role"]
    missing = [f for f in required_fields if f not in data]
    if missing:
        raise ValueError(f"Missing required fields: {', '.join(missing)}")

    # Type validation
    if not isinstance(data["name"], str) or not data["name"].strip():
        raise ValueError("Name must be a non-empty string")

    if not isinstance(data["email"], str) or "@" not in data["email"]:
        raise ValueError("Email must be a valid string containing '@'")

    if not isinstance(data["age"], int) or data["age"] < 0 or data["age"] > 150:
        raise ValueError("Age must be an integer between 0 and 150")

    if data["role"] not in ["admin", "user", "guest"]:
        raise ValueError("Role must be one of: admin, user, guest")

    # Optional field validation
    if "is_active" in data and not isinstance(data["is_active"], bool):
        raise ValueError("is_active must be a boolean")

    if "nickname" in data and not isinstance(data["nickname"], str):
        raise ValueError("nickname must be a string")

    if "created_at" in data:
        try:
            datetime.fromisoformat(data["created_at"])
        except ValueError:
            raise ValueError("created_at must be a valid ISO datetime string")

    # Create and return the typed model
    try:
        return UserInput(**data)
    except TypeError as e:
        raise ValueError(f"Invalid field: {str(e)}")


# Example usage
def process_request(request_body_json: str) -> UserInput:
    """Simulate processing a JSON request body."""
    try:
        data = json.loads(request_body_json)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON in request body")

    return validate_user_data(data)


