def read_text(path: Path) -> str:
    """Read a text file."""
    with open(path, 'r', encoding='utf-8') as f:
        return f.read()


def write_text(path: Path, content: str) -> None:
    """Write content to a text file."""
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)


def validate_input_path(path: Path, must_exist: bool = True) -> None:
    """Validate a file path exists and is a file."""
    if must_exist and not path.exists():
        sys.exit(f"Error: File '{path}' does not exist.")
    if path.exists() and not path.is_file():
        sys.exit(f"Error: '{path}' is not a file.")


def validate_output_path(path: Path, overwrite: bool = False) -> None:
    """Validate an output path, checking for conflicts."""
    if path.exists() and not overwrite:
        sys.exit(f"Error: Output file '{path}' already exists. Use --overwrite to replace.")
    # Create parent directories if needed
    if path.parent and not path.parent.exists():
        path.parent.mkdir(parents=True, exist_ok=True)

from pathlib import Path
import os

class EnvReader:
    def __init__(self, env_file='.env'):
        self.env_file = Path(env_file)
        self.values = self._load()

    def _load(self):
        """Load and parse .env file."""
        env_dict = {}
        try:
            if not self.env_file.exists():
                print(f"Warning: {self.env_file} does not exist")
                return env_dict

            with open(self.env_file, 'r') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#') or '=' not in line:
                        continue

                    key, value = line.split('=', 1)
                    value = value.strip()

                    # Handle comments
                    if '#' in value:
                        value = value.split('#')[0].strip()

                    # Remove surrounding quotes
                    if len(value) >= 2 and value[0] in ('"', "'") and value[-1] == value[0]:
                        value = value[1:-1]

                    env_dict[key.strip()] = value

        except FileNotFoundError:
            print(f"Error: {self.env_file} not found")
        except PermissionError:
            print(f"Error: No permission to read {self.env_file}")
        except Exception as e:
            print(f"Error reading {self.env_file}: {e}")

        return env_dict

    def get(self, key, default=None):
        """Get a value with default if not found."""
        # Check environment variables first
        if key in os.environ:
            return os.environ[key]

        # Then check .env file
        return self.values.get(key, default)

