from pathlib import Path
from typing import Optional


def validate_input_file(file_path: Path) -> None:
    """Validate that an input file exists and is readable."""
    if not file_path.exists():
        raise FileNotFoundError(f"Input file not found: {file_path}")
    if not file_path.is_file():
        raise ValueError(f"Input path is not a file: {file_path}")


def format_output_path(
    input_file: Path,
    output_path: Optional[str],
    suffix: str = "_processed"
) -> Path:
    """Determine the output file path with proper format."""
    if output_path:
        output = Path(output_path)
        # Check if output is a directory
        if output.suffix == "":
            output.mkdir(parents=True, exist_ok=True)
            return output / (input_file.stem + suffix + input_file.suffix)
        return output
    else:
        return input_file.with_name(input_file.stem + suffix + input_file.suffix)

