# Job models
class CreateJobRequest(BaseModel):
    """Create job request model"""
    name: str = Field(..., min_length=1, max_length=200, description="Job name")
    description: Optional[str] = Field(None, max_length=1000, description="Job description")
    processing_type: ProcessingType = Field(..., description="Type of processing to perform")
    file_type: FileType = Field(..., description="Type of file to process")
    schedule: Optional[Dict[str, Any]] = Field(
        None,
        description="Schedule configuration (e.g., cron expression or interval)"
    )
    config: Dict[str, Any] = Field(
        default_factory=dict,
        description="Processing configuration"
    )
    notifications: List[str] = Field(
        default_factory=list,
        max_length=5,
        description="List of email addresses to notify"
    )

    @field_validator("schedule")
    @classmethod
    def validate_schedule(cls, v: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
        """Validate schedule configuration"""
        if v is None:
            return v

        schedule_type = v.get("type")
        if schedule_type not in ["cron", "interval"]:
            raise ValueError("Schedule type must be 'cron' or 'interval'")

        if schedule_type == "cron":
            # Validate cron expression (simplified validation)
            cron = v.get("expression", "")
            if not isinstance(cron, str) or len(cron.split()) != 5:
                raise ValueError("Invalid cron expression provided")

        if schedule_type == "interval":
            # Validate interval
            interval = v.get("minutes")
            if not isinstance(interval, int) or interval < 1:
                raise ValueError("Interval must be positive integer (minutes)")

        return v

    @field_validator("notifications")
    @classmethod
    def validate_notifications(cls, v: List[str]) -> List[str]:
        """Validate email notifications"""
        for email in v:
            if "@" not in email or not email.strip():
                raise ValueError(f"Invalid email address: {email}")
        return v

class JobUploadRequest(BaseModel):
    """File upload request model"""
    file_name: str = Field(..., min_length=1, max_length=255, description="Name of the file")
    file_size: int = Field(..., gt=0, le=10485760, description="File size in bytes (max 10MB)")
    checksum: str = Field(..., min_length=32, max_length=64, description="MD5 or SHA256 checksum")

    @field_validator("file_name")
    @classmethod
    def validate_file_name(cls, v: str) -> str:
        """Validate file name"""
        allowed_extensions = ['.csv', '.xlsx', '.xls']
        if not any(v.lower().endswith(ext) for ext in allowed_extensions):
            raise ValueError(f"File must be one of: {', '.join(allowed_extensions)}")
        return v

    @field_validator("checksum")
    @classmethod
    def validate_checksum(cls, v: str) -> str:
        """Validate checksum format"""
        if not v.isalnum() or len(v) not in [32, 64]:
            raise ValueError("Checksum must be 32 chars (MD5) or 64 chars (SHA256) hex string")
        return v

