from typing import Any, Dict, List, Optional, Union


def read_file(filepath: Union[str, Path], encoding: str = "utf-8") -> str:
    """Read a file and return its contents as a string."""
    with open(filepath, "r", encoding=encoding) as f:
        return f.read()


def write_file(filepath: Union[str, Path], content: str, encoding: str = "utf-8") -> None:
    """Write content to a file."""
    with open(filepath, "w", encoding=encoding) as f:
        f.write(content)


def read_lines(filepath: Union[str, Path], encoding: str = "utf-8") -> List[str]:
    """Read a file and return its lines as a list."""
    with open(filepath, "r", encoding=encoding) as f:
        return [line.rstrip("\n") for line in f]


def write_lines(filepath: Union[str, Path], lines: List[str], encoding: str = "utf-8") -> None:
    """Write a list of lines to a file, one per line."""
    with open(filepath, "w", encoding=encoding) as f:
        f.write("\n".join(lines))
        f.write("\n")


def load_json(filepath: Union[str, Path], encoding: str = "utf-8") -> Dict[str, Any]:
    """Load a JSON file and return the parsed data."""
    with open(filepath, "r", encoding=encoding) as f:
        return json.load(f)


def save_json(data: Any, filepath: Union[str, Path], encoding: str = "utf-8") -> None:
    """Save data to a JSON file."""
    with open(filepath, "w", encoding=encoding) as f:
        json.dump(data, f, indent=2, ensure_ascii=False)


def format_text(text: str, max_width: Optional[int] = None) -> str:
    """Format text, optionally wrapping to a maximum width."""
    if not max_width:
        return text

    lines = []
    for paragraph in text.split("\n"):
        if not paragraph:
            lines.append("")
            continue
        words = paragraph.split()
        current_line = []
        current_length = 0

        for word in words:
            if current_length + len(word) + (1 if current_line else 0) > max_width:
                if current_line:
                    lines.append(" ".join(current_line))
                    current_line = []
                    current_length = 0
            current_line.append(word)
            current_length += len(word) + (1 if len(current_line) > 1 else 0)

        if current_line:
            lines.append(" ".join(current_line))

    return "\n".join(lines)


def normalize_text(text: str) -> str:
    """Normalize text by lowercasing and removing extra whitespace."""
    return " ".join(text.lower().strip().split())


def parse_bool(value: str) -> bool:
    """Parse a string as a boolean."""
    value = value.lower().strip()
    if value in ("true", "yes", "y", "1"):
        return True
    if value in ("false", "no", "n", "0"):
        return False
    raise ValueError(f"Cannot parse '{value}' as a boolean")


def is_file_readable(filepath: Union[str, Path]) -> bool:
    """Check if a file exists and is readable."""
    return os.path.isfile(filepath) and os.access(filepath, os.R_OK)

