def find_command(args: argparse.Namespace) -> int:
    """Find the closest match(es) from a list of names."""
    from .utils import read_lines

    # Get the query string
    query = args.query

    # Get the list of names
    names = []
    if args.names:
        names = args.names
    elif args.file:
        names = read_lines(args.file)
    else:
        names = read_lines(sys.stdin) if not sys.stdin.isatty() else []

    if not names:
        print("Error: No names provided. Use --names, --file, or pipe names via stdin.", file=sys.stderr)
        return 1

    # Normalize query
    query_normalized = normalize_text(query) if args.ignore_case else query.strip()

    # Find matches
    matches = find_closest_matches(
        query_normalized,
        [normalize_text(name) if args.ignore_case else name.strip() for name in names],
        limit=args.limit,
        threshold=args.threshold,
    )

    # Display results
    if args.json:
        output = [
            {"name": name, "score": round(score, 3), "is_exact": score >= 1.0}
            for name, score in matches
        ]
        print(json.dumps(output, indent=2))
    else:
        if args.verbose:
            for name, score in matches:
                match_type = "EXACT" if score >= 1.0 else "SHOWN"
                print(f"{match_type:5s} | {score:.3f} | {name}")
        else:
            for name, score in matches:
                print(name)

    # Exit with error if no match found
    return 0 if matches else 1


def find_closest_matches(
    query: str,
    names: Sequence[str],
    limit: int = 10,
    threshold: float = 0.6,
) -> List[Tuple[str, float]]:
    """Find the closest matches to a query from a list of names.

    Args:
        query: The query string to match against.
        names: List of names to search through.
        limit: Maximum number of matches to return.
        threshold: Minimum similarity score (0-1) to consider.

    Returns:
        List of (name, similarity_score) tuples sorted by score descending.
    """
    if not names:
        return []

    # Use difflib's SequenceMatcher for string similarity
    matcher = difflib.SequenceMatcher()
    scored_matches = []

    for name in names:
        matcher.set_seqs(query, name)
        ratio = matcher.ratio()

        # Also check if one is a substring of the other
        if query in name or name in query:
            ratio = max(ratio, 0.9)

        if ratio >= threshold:
            scored_matches.append((name, ratio))

    # Sort by score descending, then by name
    scored_matches.sort(key=lambda x: (-x[1], x[0]))

    # Return top matches
    return scored_matches[:limit]


