def stats_command(args: argparse.Namespace) -> int:
    """Calculate basic statistics for a list of numbers."""
    numbers = []

    if args.numbers:
        numbers = args.numbers
    else:
        raw = []
        if args.file:
            raw.extend(read_lines(args.file))
        elif not sys.stdin.isatty():
            raw.extend(sys.stdin.read().splitlines())

        for line in raw:
            for token in line.replace(",", " ").split():
                try:
                    numbers.append(float(token))
                except ValueError:
                    continue

    if not numbers:
        print("Error: No numbers provided", file=sys.stderr)
        return 1

    if args.average:
        print(f"{sum(numbers) / len(numbers):.6f}")
        return 0

    if args.min:
        print(f"{min(numbers):.6f}")
        return 0

    if args.max:
        print(f"{max(numbers):.6f}")
        return 0

    # Default: show all stats
    stats = {
        "count": len(numbers),
        "min": min(numbers),
        "max": max(numbers),
        "average": sum(numbers) / len(numbers),
        "median": calculate_median(numbers),
        "variance": calculate_variance(numbers),
        "deviation": math.sqrt(calculate_variance(numbers)),
    }

    for key, value in stats.items():
        print(f"{key:10s}: {value:.6f}")

    return 0


def calculate_median(numbers: Sequence[float]) -> float:
    """Calculate the median of a list of numbers."""
    sorted_nums = sorted(numbers)
    n = len(sorted_nums)
    if n % 2 == 1:
        return sorted_nums[n // 2]
    return (sorted_nums[n // 2 - 1] + sorted_nums[n // 2]) / 2


def calculate_variance(numbers: Sequence[float]) -> float:
    """Calculate the population variance of a list of numbers."""
    avg = sum(numbers) / len(numbers)
    return sum((x - avg) ** 2 for x in numbers) / len(numbers)


