"""Shared helper functions for pytoolbox."""
import sys
from pathlib import Path


def read_input(file_path=None):
    """Read input from file or stdin."""
    if file_path and file_path != '-':
        try:
            path = Path(file_path)
            if not path.exists():
                raise FileNotFoundError(f"File not found: {file_path}")
            return path.read_text()
        except Exception as e:
            raise ValueError(f"Cannot read file {file_path}: {e}")
    else:
        # Read from stdin
        if sys.stdin.isatty():
            # Interactive mode - read until EOF
            lines = []
            print("Enter input (Ctrl-D to finish):", file=sys.stderr)
            try:
                while True:
                    line = input()
                    lines.append(line)
            except EOFError:
                pass
            return '\n'.join(lines)
        else:
            # Piped input
            return sys.stdin.read()


def write_output(data, file_path=None):
    """Write output to file or stdout."""
    if file_path and file_path != '-':
        path = Path(file_path)
        path.write_text(data)
    else:
        if data:
            sys.stdout.write(data + '\n')
        else:
            sys.stdout.write("")


def format_error(message):
    """Format error message."""
    return f"Error: {message}"


def parse_bool(value):
    """Parse boolean value from string."""
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.lower() in ('true', 'yes', '1', 'y', 't')
    return bool(value)


def read_raw_input(file_path=None):
    """Read raw bytes from file or stdin."""
    if file_path and file_path != '-':
        try:
            path = Path(file_path)
            if not path.exists():
                raise FileNotFoundError(f"File not found: {file_path}")
            return path.read_bytes()
        except Exception as e:
            raise ValueError(f"Cannot read file {file_path}: {e}")
    else:
        return sys.stdin.buffer.read()


def write_raw_output(data, file_path=None):
    """Write raw bytes to file or stdout."""
    if file_path and file_path != '-':
        path = Path(file_path)
        path.write_bytes(data)
    else:
        sys.stdout.buffer.write(data)

