from dataclasses import dataclass, field
from typing import Optional
import re

@dataclass
class UserData:
    username: str
    email: str
    age: int
    is_active: bool = True

    def __post_init__(self):
        # Validate in the post_init
        if not isinstance(self.username, str) or len(self.username) < 3:
            raise ValueError("Username must be a string with min length 3")
        if not isinstance(self.email, str) or not re.match(r"^[^@]+@[^@]+\.[^@]+$", self.email):
            raise ValueError("Invalid email format")
        if not isinstance(self.age, int) or not (0 <= self.age <= 120):
            raise ValueError("Age must be an integer between 0 and 120")
        if not isinstance(self.is_active, bool):
            raise ValueError("is_active must be a boolean")

def validate_request(data: dict) -> UserData:
    try:
        return UserData(**data)
    except (TypeError, ValueError) as e:
        raise ValueError(f"Invalid input: {e}")

