    email: str
    age: int
    created_at: Optional[datetime]

def validate_typed_dict(data: dict, expected_type: type) -> UserRequest:
    """Validate a dict against a TypedDict structure"""
    if not isinstance(data, dict):
        raise ValueError("Request must be a dictionary")

    type_hints = get_type_hints(expected_type)

    # Validate required keys
    for key, expected_type in type_hints.items():
        if key not in data:
            raise ValueError(f"Missing required field: {key}")

        # Basic type checking
        if expected_type == int and not isinstance(data[key], int):
            raise ValueError(f"Field '{key}' must be an integer")
        elif expected_type == str and not isinstance(data[key], str):
            raise ValueError(f"Field '{key}' must be a string")
        elif expected_type == bool and not isinstance(data[key], bool):
            raise ValueError(f"Field '{key}' must be a boolean")

    return UserRequest(**data)

