"""Individual helper commands for the toolbox."""

import json
from typing import Any, Dict, Type, TypeVar, get_type_hints
from dataclasses import dataclass, fields, is_dataclass
from enum import Enum
from datetime import datetime, date
from pathlib import Path
import uuid
import re


T = TypeVar('T')


@dataclass
class ValidationError(Exception):
    """Raised when request body validation fails."""
    errors: Dict[str, str]

    def __init__(self, errors: Dict[str, str]):
        self.errors = errors
        super().__init__(f"Validation failed: {errors}")


class RequestParser:
    """
    Parse and validate a request body into a typed model.

    Supports:
    - dataclasses as models
    - Basic types: str, int, float, bool, datetime, date, UUID, Path
    - Enums
    - Nested dataclasses
    - Optional/union types
    - Lists of supported types
    - Dictionaries with string keys

    Usage:
        @dataclass
        class User:
            name: str
            age: int
            email: str = None

        parser = RequestParser(User)
        user = parser.parse({'name': 'Alice', 'age': 30})
    """

    def __init__(self, model: Type[T]):
        if not is_dataclass(model):
            raise ValueError(f"Model must be a dataclass, got {model}")
        self.model = model
        self.model_fields = {f.name: f for f in fields(model)}
        self.type_hints = get_type_hints(model)

    def parse(self, body: Any) -> T:
        """
        Parse and validate a request body into the typed model.

        Args:
            body: The request body (dict, JSON string, or bytes)

        Returns:
            An instance of the model

        Raises:
            ValidationError: If validation fails with details of errors
        """
        # Coerce input to dict
        try:
            data = self._coerce_to_dict(body)
        except (json.JSONDecodeError, ValueError) as e:
            raise ValidationError({'_body': f"Invalid JSON body: {str(e)}"})

        if not isinstance(data, dict):
            raise ValidationError({'_body': "Request body must be an object"})

        errors = {}
        result = {}

        # Validate each field
        for field_name, field in self.model_fields.items():
            # Check for required fields
            if field_name not in data:
                if field.default is not dataclasses.MISSING:
                    result[field_name] = field.default
                    continue
                elif field.default_factory is not dataclasses.MISSING:
                    result[field_name] = field.default_factory()
                    continue
                else:
                    errors[field_name] = f"Field is required"
                    continue

            value = data[field_name]
            field_type = self.type_hints.get(field_name, field.type)

            try:
                # Check for None if field allows it
                if value is None:
                    if self._type_allows_none(field_type):
                        result[field_name] = None
                        continue
                    else:
                        errors[field_name] = "Field cannot be None"
                        continue

                # Parse the value
                parsed_value = self._parse_value(value, field_type, field_name)
                result[field_name] = parsed_value

            except ValidationError as e:
                for k, v in e.errors.items():
                    errors[f"{field_name}.{k}" if k else field_name] = v
                continue
            except (ValueError, TypeError, json.JSONDecodeError) as e:
                errors[field_name] = f"Invalid value: {str(e)}"
                continue

        # Don't allow unknown fields
        unknown_fields = set(data.keys()) - set(self.model_fields.keys())
        if unknown_fields:
            for field in unknown_fields:
                errors[field] = "Unknown field"

        if errors:
            raise ValidationError(errors)

        try:
            return self.model(**result)
        except Exception as e:
            raise ValidationError({'_model': f"Failed to create model instance: {str(e)}"})

    def _coerce_to_dict(self, body: Any) -> Dict[str, Any]:
        """Coerce various input types to a dict."""
        if isinstance(body, dict):
            return body
        elif isinstance(body, bytes):
            return json.loads(body.decode('utf-8'))
        elif isinstance(body, str):
            # Try to parse as JSON, but strip if it looks like JSON with leading/trailing whitespace
            body = body.strip()
            if body.startswith('{'):
                return json.loads(body)
            else:
                # Try to parse as key=value pairs
                result = {}
                for pair in body.split('&'):
                    if '=' in pair:
                        key, value = pair.split('=', 1)
                        result[key] = value
                    elif pair.strip():
                        result[pair.strip()] = True
                return result
        else:
            raise ValueError(f"Cannot coerce {type(body)} to dict")

    def _type_allows_none(self, field_type) -> bool:
        """Check if a type allows None."""
        if hasattr(field_type, '__origin__'):
            return field_type.__origin__ is Union and type(None) in field_type.__args__
        return False

    def _parse_value(self, value: Any, field_type: Type, field_name: str) -> Any:
        """Parse a single value based on its type."""
        # Handle Union types
        if hasattr(field_type, '__origin__'):
            origin = field_type.__origin__

            # Optional[X] == Union[X, None]
            if origin is Union:
                non_none_types = [t for t in field_type.__args__ if t is not type(None)]
                if len(non_none_types) == 1:
                    return self._parse_value(value, non_none_types[0], field_name)
                else:
                    # Try each type
                    errors = []
                    for t in non_none_types:
                        try:
                            return self._parse_value(value, t, field_name)
                        except (ValueError, TypeError) as e:
                            errors.append(str(e))
                    raise ValueError(f"Could not match any type: {'; '.join(errors)}")

            # List[X]
            elif origin in (list, List):
                if not isinstance(value, list):
                    raise ValueError(f"Expected list, got {type(value)}")
                item_type = field_type.__args__[0]
                return [self._parse_value(item, item_type, field_name) for item in value]

            # Dict[str, X]
            elif origin in (dict, Dict):
                if not isinstance(value, dict):
                    raise ValueError(f"Expected dict, got {type(value)}")
                key_type = field_type.__args__[0]
                value_type = field_type.__args__[1]
                if key_type is not str:
                    raise ValueError(f"Dict keys must be strings")
                return {
                    k: self._parse_value(v, value_type, field_name)
                    for k, v in value.items()
                }

        # Handle basic types
        if field_type is str:
            return str(value) if not isinstance(value, bool) else str(value).lower()
        elif field_type is int:
            if isinstance(value, bool):
                raise ValueError("Cannot convert bool to int")
            return int(value)
        elif field_type is float:
            if isinstance(value, bool):
                raise ValueError("Cannot convert bool to float")
            return float(value)
        elif field_type is bool:
            if isinstance(value, str):
                return value.lower() in ('true', '1', 'yes', 'y')
            return bool(value)
        elif field_type is datetime:
            if isinstance(value, str):
                try:
                    return datetime.fromisoformat(value)
                except ValueError:
                    raise ValueError(f"Invalid datetime format: {value}")
            elif isinstance(value, datetime):
                return value
            else:
                raise ValueError(f"Cannot convert {type(value)} to datetime")
        elif field_type is date:
            if isinstance(value, str):
                try:
                    return date.fromisoformat(value)
                except ValueError:
                    raise ValueError(f"Invalid date format: {value}")
            elif isinstance(value, date):
                return value
            else:
                raise ValueError(f"Cannot convert {type(value)} to date")
        elif field_type is uuid.UUID:
            if isinstance(value, str):
                try:
                    return uuid.UUID(value)
                except ValueError:
                    raise ValueError(f"Invalid UUID format: {value}")
            elif isinstance(value, uuid.UUID):
                return value
            else:
                raise ValueError(f"Cannot convert {type(value)} to UUID")
        elif field_type is Path:
            if isinstance(value, str):
                return Path(value)
            elif isinstance(value, Path):
                return value
            else:
                raise ValueError(f"Cannot convert {type(value)} to Path")
        elif isinstance(field_type, type) and issubclass(field_type, Enum):
            try:
                return field_type(value)
            except (ValueError, KeyError):
                raise ValueError(f"Invalid enum value: {value}")
        elif is_dataclass(field_type):
            # Nested dataclass
            if not isinstance(value, dict):
                raise ValueError(f"Expected dict for {field_name}, got {type(value)}")
            parser = RequestParser(field_type)
            return parser.parse(value)
        else:
            # Fallback: try to create instance
            try:
                return field_type(value)
            except Exception as e:
                raise ValueError(f"Cannot convert to {field_type}: {str(e)}")


def parse_request_body(body: Any, model: Type[T]) -> Dict[str, Any]:
    """
    Parse and validate a request body into a typed model.

    This is the main entry point for the feature. It can be used with
    any dataclass model.

    Args:
        body: The request body (dict, JSON string, or bytes)
        model: The dataclass model class

    Returns:
        An instance of the model

    Example:
        @dataclass
        class User:
            name: str
            age: int
            email: str = None

        user = parse_request_body(request_data, User)
    """
    parser = RequestParser(model)
    return parser.parse(body)

"""

    # Handle different input types
    if isinstance(body, dict):
        data = body
    elif isinstance(body, bytes):
        try:
            data = json.loads(body.decode('utf-8'))
        except json.JSONDecodeError as e:
            error_msg = f"Malformed JSON: {str(e)}"
            raise ParseError(
                error_msg,
                ValidationErrorCode.MALFORMED_JSON,
                {"position": e.pos, "line": e.lineno, "column": e.colno}
            )
    elif isinstance(body, str):
        try:
            data = json.loads(body)
        except json.JSONDecodeError as e:
            error_msg = f"Malformed JSON: {str(e)}"
            raise ParseError(
                error_msg,
                ValidationErrorCode.MALFORMED_JSON,
                {"position": e.pos, "line": e.lineno, "column": e.colno}
            )
    else:
        error_msg = f"Unsupported body type: {type(body).__name__}"
        raise ParseError(error_msg, ValidationErrorCode.INVALID_REQUEST)

    # Ensure data is a dict
    if not isinstance(data, dict):
        error_msg = "Request body must be a JSON object"
        raise ParseError(
            error_msg,
            ValidationErrorCode.INVALID_REQUEST,
            {"received_type": type(data).__name__}
        )

    # Validate required fields exist (basic check)
    required_fields = get_required_fields(model)
    missing_fields = [field for field in required_fields if field not in data]
    if missing_fields:
        error_msg = f"Missing required fields: {', '.join(missing_fields)}"
        raise ParseError(
            error_msg,
            ValidationErrorCode.MISSING_FIELDS,
            {"missing_fields": missing_fields}
        )

    # Validate data types
    type_errors = validate_types(model, data)
    if type_errors:
        error_msg = "Type validation failed"
        raise ParseError(
            error_msg,
            ValidationErrorCode.INVALID_TYPES,
            {"type_errors": type_errors}
        )

    # Parse and validate with Pydantic
    try:
        # Configure parser based on strict mode
        parser_config = type('Config', (), {
            "extra": "forbid" if strict else "ignore"
        })

        # Create a temporary model class with the config
        temp_model = type(
            f"Validated_{model.__name__}",
            (model,),
            {"Config": parser_config}
        )

        # Validate and return the model instance
        validated = temp_model(**data)
        return validated

    except ValidationError as e:
        error_details = e.errors()
        formatted_errors = []
        for err in error_details:
            formatted_errors.append({
                "field": ".".join(map(str, err["loc"])),
                "type": err["type"],
                "message": err["msg"]
            })

        error_msg = "Validation failed"
        raise ParseError(
            error_msg,
            ValidationErrorCode.VALIDATION_ERROR,
            {"validation_errors": formatted_errors}
        )

    except Exception as e:
        error_msg = f"Unexpected error during validation: {str(e)}"
        raise ParseError(error_msg, ValidationErrorCode.VALIDATION_ERROR)


def get_required_fields(model: Type[BaseModel]) -> list[str]:
    """Get list of required field names from a Pydantic model"""
    required = []
    for name, field in model.model_fields.items():
        if field.is_required():
            required.append(name)
    return required


def validate_types(model: Type[BaseModel], data: Dict[str, Any]) -> list[Dict[str, Any]]:
    """Perform basic type checking before Pydantic validation"""
    type_errors = []

    for name, field in model.model_fields.items():
        if name in data:
            expected_type = field.annotation
            actual_value = data[name]

            # Skip None values for optional fields
            if actual_value is None and not field.is_required():
                continue

            # Basic type checks
            if expected_type is int and not isinstance(actual_value, (int, float)):
                type_errors.append({
                    "field": name,
                    "expected": "int",
                    "received": type(actual_value).__name__
                })
            elif expected_type is float and not isinstance(actual_value, (int, float)):
                type_errors.append({
                    "field": name,
                    "expected": "float",
                    "received": type(actual_value).__name__
                })
            elif expected_type is str and not isinstance(actual_value, str):
                type_errors.append({
                    "field": name,
                    "expected": "string",
                    "received": type(actual_value).__name__
                })
            elif expected_type is bool and not isinstance(actual_value, bool):
                type_errors.append({
                    "field": name,
                    "expected": "boolean",
                    "received": type(actual_value).__name__
                })
            elif expected_type is list and not isinstance(actual_value, list):
                type_errors.append({
                    "field": name,
                    "expected": "array",
                    "received": type(actual_value).__name__
                })
            elif expected_type is dict and not isinstance(actual_value, dict):
                type_errors.append({
                    "field": name,
                    "expected": "object",
                    "received": type(actual_value).__name__
                })

    return type_errors


# Example usage and additional helpers

def create_http_exception(e: ParseError) -> HTTPException:
    """Convert ParseError to HTTPException for FastAPI endpoints"""
    status_code = 400
    if e.error_code == ValidationErrorCode.MALFORMED_JSON:
        status_code = 400
    elif e.error_code == ValidationErrorCode.MISSING_FIELDS:
        status_code = 422

    return HTTPException(
        status_code=status_code,
        detail={
            "error": e.error_code.value,
            "message": e.message,
            "details": e.details
        }
    )


# Alternative async wrapper for FastAPI endpoints
async def validate_request_body(
    request: Any,
    model: Type[T],
    *,
    strict: bool = False
) -> T:
    """
    Async wrapper that reads the request body and validates it.
    Useful for FastAPI Request objects.
    """
    try:
        body = await request.body()
        return parse_request_body(body, model, strict=strict)
    except ParseError as e:
        raise create_http_exception(e)

