def levenshtein_distance(s1, s2):
    """Calculate the Levenshtein distance between two strings"""
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)

    if len(s2) == 0:
        return len(s1)

    previous_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        current_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = previous_row[j + 1] + 1
            deletions = current_row[j] + 1
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row

    return previous_row[-1]

def find_closest_match_v2(query, names_list):
    """Alternative implementation using Levenshtein distance"""
    if not names_list:
        return None, 0.0

    query = query.lower()
    best_match = None
    best_score = 0.0

    for name in names_list:
        name_lower = name.lower()
        distance = levenshtein_distance(query, name_lower)
        max_len = max(len(query), len(name_lower))
        similarity = 1 - (distance / max_len) if max_len > 0 else 1.0

        if similarity > best_score:
            best_score = similarity
            best_match = name

    return best_match, best_score

