class ValidationError(Exception):
    """Custom exception for validation errors with detailed field info"""
    def __init__(self, errors: Dict[str, str]):
        self.errors = errors
        super().__init__(f"Validation failed: {errors}")


class BaseModel:
    """Base class for typed models with validation capabilities"""

    @classmethod
    def parse(cls, data: Union[Dict, str, bytes]) -> 'BaseModel':
        """
        Parse and validate input data into the model
        Raises ValidationError on invalid input
        """
        # Parse JSON if string/bytes
        if isinstance(data, (str, bytes)):
            try:
                if isinstance(data, bytes):
                    data = data.decode('utf-8')
                data = json.loads(data)
            except json.JSONDecodeError as e:
                raise ValidationError({"__root__": f"Invalid JSON: {str(e)}"})

        if not isinstance(data, dict):
            raise ValidationError({"__root__": "Request body must be a JSON object"})

        # Get type hints for validation
        type_hints = get_type_hints(cls)

        # Track validation errors
        errors = {}
        validated_data = {}

        # Validate each field
        for field_name, field_type in type_hints.items():
            if field_name == 'model_config':
                continue

            if field_name not in data:
                # Check if field has default value
                default = getattr(cls, field_name, None)
                if callable(default):
                    default = default()
                validated_data[field_name] = default
            else:
                try:
                    validated_data[field_name] = cls._validate_field(
                        field_name, data[field_name], field_type
                    )
                except ValidationError as e:
                    errors.update(e.errors)

        # Check for unexpected fields
        expected_fields = set(type_hints.keys()) - {'model_config'}
        unexpected = set(data.keys()) - expected_fields
        if unexpected:
            for field in unexpected:
                errors[field] = "Unexpected field"

        if errors:
            raise ValidationError(errors)

        # Create instance
        return cls(**validated_data)

    @classmethod
    def _validate_field(cls, field_name: str, value: Any, field_type: Any) -> Any:
        """Validate a single field value against its type"""
        origin = get_origin(field_type)

        # Handle Optional[X] or Union types
        if origin is Union:
            # Try each type in the union
            last_error = None
            for type_arg in get_args(field_type):
                try:
                    return cls._validate_field(field_name, value, type_arg)
                except ValidationError as e:
                    last_error = e
            raise ValidationError({field_name: f"Invalid type for {field_name}"})

        # Handle lists
        if origin is list:
            if not isinstance(value, list):
                raise ValidationError({field_name: f"Expected list, got {type(value).__name__}"})
            item_type = get_args(field_type)[0]
            try:
                return [cls._validate_field(f"{field_name}[{i}]", item, item_type) 
                       for i, item in enumerate(value)]
            except ValidationError as e:
                raise ValidationError({f"{field_name}": f"Invalid list items: {e.errors}"})

        # Handle dicts
        if origin is dict:
            if not isinstance(value, dict):
                raise ValidationError({field_name: f"Expected dict, got {type(value).__name__}"})
            key_type, value_type = get_args(field_type)
            try:
                return {
                    cls._validate_field(f"{field_name}.key", k, key_type): 
                    cls._validate_field(f"{field_name}.value", v, value_type)
                    for k, v in value.items()
                }
            except ValidationError as e:
                raise ValidationError({f"{field_name}": f"Invalid dict entries: {e.errors}"})

        # Handle enums
        if isinstance(field_type, type) and issubclass(field_type, Enum):
            try:
                return field_type(value)
            except (ValueError, KeyError):
                allowed = [e.value for e in field_type]
                raise ValidationError({field_name: f"Invalid value. Allowed: {allowed}"})

        # Handle datetime
        if field_type is datetime:
            if isinstance(value, datetime):
                return value
            if isinstance(value, str):
                try:
                    return datetime.fromisoformat(value)
                except ValueError:
                    raise ValidationError({field_name: "Invalid datetime format. Use ISO format"})
            raise ValidationError({field_name: "Invalid datetime type"})

        # Handle nested models
        if isinstance(field_type, type) and issubclass(field_type, BaseModel):
            return field_type.parse(value)

        # Handle basic types
        if field_type in (str, int, float, bool):
            if field_type is str:
                if not isinstance(value, str):
                    raise ValidationError({field_name: f"Expected string, got {type(value).__name__}"})
                return value
            elif field_type is int:
                if isinstance(value, bool) or not isinstance(value, (int, float)):
                    raise ValidationError({field_name: f"Expected integer, got {type(value).__name__}"})
                if isinstance(value, float):
                    if not value.is_integer():
                        raise ValidationError({field_name: "Expected integer, got float"})
                    return int(value)
                return value
            elif field_type is float:
                if isinstance(value, bool) or not isinstance(value, (int, float)):
                    raise ValidationError({field_name: f"Expected number, got {type(value).__name__}"})
                return float(value)
            elif field_type is bool:
                if not isinstance(value, bool):
                    raise ValidationError({field_name: f"Expected boolean, got {type(value).__name__}"})
                return value

        return value


