import re
import phonenumbers
from phonenumbers import carrier, geocoder, timezone

def validate_and_format_phone(phone_number, country_code=None):
    """
    Validate and format a phone number to international format.

    Args:
        phone_number (str): The phone number to validate/format
        country_code (str, optional): Two-letter country code (e.g., 'US', 'GB')

    Returns:
        tuple: (is_valid, formatted_number, error_message)
    """
    try:
        # Remove all whitespace and common separators
        cleaned_number = re.sub(r'[\s\-\.\(\)]', '', phone_number)

        # Check if number starts with '+'
        if cleaned_number.startswith('+'):
            # Parse as international number
            parsed_number = phonenumbers.parse(cleaned_number)
        else:
            # If country code provided, use it for parsing
            if country_code:
                parsed_number = phonenumbers.parse(cleaned_number, country_code)
            else:
                # Default to US if no country code provided
                parsed_number = phonenumbers.parse(cleaned_number, "US")

        # Validate the number
        if not phonenumbers.is_valid_number(parsed_number):
            return (False, None, "Invalid phone number")

        # Check if it's a possible number
        if not phonenumbers.is_possible_number(parsed_number):
            return (False, None, "Phone number is not possible")

        # Format in international format
        international_format = phonenumbers.format_number(
            parsed_number, 
            phonenumbers.PhoneNumberFormat.INTERNATIONAL
        )

        # Format in E.164 format (without spaces)
        e164_format = phonenumbers.format_number(
            parsed_number, 
            phonenumbers.PhoneNumberFormat.E164
        )

        # Get additional information
        region = geocoder.description_for_number(parsed_number, "en")
        phone_type = get_phone_type(parsed_number)

        return (True, e164_format, f"Valid {phone_type} number in {region}")

    except phonenumbers.NumberParseException as e:
        return (False, None, f"Parse error: {str(e)}")
    except Exception as e:
        return (False, None, f"Unexpected error: {str(e)}")

def get_phone_type(phone_number):
    """Get the type of phone number."""
    if carrier.is_mobile_number(phone_number):
        return "mobile"
    elif phonenumbers.is_number_match(phone_number, phonenumbers.parse("+1234567890")) != 0:
        return "fixed line"
    else:
        return "valid"

def main():
    """Example usage of the phone number validator."""
    test_numbers = [
        "+14155552671",  # Valid US number
        "415-555-2671",   # US format without country code
        "14155552671",    # Without + sign
        "+442071838750",  # UK number
        "+916123456789",  # India number
        "555-555-5555",   # Invalid US number
        "",               # Empty string
        "not-a-number"    # Invalid input
    ]

    print("Phone Number Validation Results:")
