import re
from typing import Optional, Tuple
from dataclasses import dataclass

@dataclass
class PhoneValidationResult:
    """Result of phone number validation and formatting"""
    is_valid: bool
    international_format: Optional[str] = None
    country_code: Optional[str] = None
    national_number: Optional[str] = None
    error_message: Optional[str] = None


class PhoneNumberValidator:
    """
    Phone number validation and international format conversion utility.
    Supports common formats including US, UK, and international numbers.
    """

    # Common country codes with their patterns
    COUNTRY_CODES = {
        '1': {'name': 'US/CA', 'length': 10, 'pattern': r'^[2-9]\d{2}[2-9]\d{6}$'},
        '44': {'name': 'UK', 'length': 10, 'pattern': r'^[1-9]\d{9}$'},
        '61': {'name': 'AU', 'length': 9, 'pattern': r'^[2-9]\d{8}$'},
        '49': {'name': 'DE', 'length': 10, 'pattern': r'^[1-9]\d{9}$'},
        '33': {'name': 'FR', 'length': 9, 'pattern': r'^[1-9]\d{8}$'},
        '81': {'name': 'JP', 'length': 10, 'pattern': r'^[1-9]\d{9}$'},
        '91': {'name': 'IN', 'length': 10, 'pattern': r'^[6-9]\d{9}$'},
    }

    def __init__(self):
        self.phone_pattern = re.compile(r'^\+?(\d{1,3})?[-.\s]?\(?(\d{1,4})\)?[-.\s]?(\d{1,4})[-.\s]?(\d{1,4})[-.\s]?(\d{1,4})$')

    def _clean_number(self, phone: str) -> str:
        """Remove non-numeric characters except leading +"""
        phone = phone.strip()
        if phone.startswith('+'):
            return '+' + re.sub(r'[^\d]', '', phone)
        return re.sub(r'[^\d]', '', phone)

    def _split_country_code(self, cleaned: str) -> Tuple[str, str]:
        """Try to split number into country code and national number"""
        # If starts with +, try to extract country code
        if cleaned.startswith('+'):
            number = cleaned[1:]
            for i in range(1, 4):  # Check 1-3 digit country codes
                cc = number[:i]
                if cc in self.COUNTRY_CODES:
                    return cc, number[i:]

        # Default to US/Canada if 10 digits (no country code)
        if len(cleaned) == 10:
            return '1', cleaned

        # Try to find country code for other lengths
        for cc in sorted(self.COUNTRY_CODES.keys(), key=len, reverse=True):
            if cleaned.startswith(cc) and len(cleaned) == len(cc) + self.COUNTRY_CODES[cc]['length']:
                return cc, cleaned[len(cc):]

        return '', cleaned

    def validate_number(self, number: str) -> PhoneValidationResult:
        """
        Validate and format phone number to international format

        Args:
            number: Phone number in various formats (e.g., "+1 234-567-8900", 
                   "(555) 123-4567", "020 7946 0958", "+44 20 7946 0958")

        Returns:
            PhoneValidationResult with validation status and formatted number
        """
        if not number or not isinstance(number, str):
            return PhoneValidationResult(
                is_valid=False, 
                error_message="Phone number is required and must be a string"
            )

        # Clean the number
        cleaned = self._clean_number(number)

        if not cleaned or (not cleaned.startswith('+') and len(re.sub(r'^\+\d+', '', cleaned)) == 0):
            return PhoneValidationResult(
                is_valid=False,
                error_message="Phone number contains no digits"
            )

        # Try to split country code
        country_code, national = self._split_country_code(cleaned)

        if not country_code:
            # Try to infer from length
            if len(national) == 10 and national.startswith('1'):
                return PhoneValidationResult(
                    is_valid=False,
                    error_message="Use +1 for US/Canada numbers (e.g., +1XXXXXXXXXX)"
                )
            elif len(national) == 10:
                return PhoneValidationResult(
                    is_valid=False,
                    error_message="Could not determine country code. Use international format with + prefix"
                )
            else:
                return PhoneValidationResult(
                    is_valid=False,
                    error_message="Unable to determine country code"
                )

        # Validate national number length
        country_info = self.COUNTRY_CODES[country_code]
        if len(national) != country_info['length']:
            return PhoneValidationResult(
                is_valid=False,
                error_message=f"Invalid national number length for {country_info['name']}. "
                            f"Expected {country_info['length']} digits, got {len(national)}"
            )

        # Validate national number pattern
        if not re.match(country_info['pattern'], national):
            return PhoneValidationResult(
                is_valid=False,
                error_message=f"Invalid national number pattern for {country_info['name']}"
            )

        # Format to international standard
        international_format = f"+{country_code} {national}"

        return PhoneValidationResult(
            is_valid=True,
            international_format=international_format,
            country_code=country_code,
            national_number=national
        )

    def format_number(self, number: str) -> str:
        """
        Convenience method that returns just the formatted number

        Raises:
            ValueError: If the number is invalid
        """
        result = self.validate_number(number)
        if not result.is_valid:
            raise ValueError(f"Invalid phone number: {result.error_message}")
        return result.international_format

    def validate_batch(self, numbers: list[str]) -> list[PhoneValidationResult]:
        """Validate multiple phone numbers at once"""
        return [self.validate_number(num) for num in numbers]


# Create a singleton instance for easy use
phone_validator = PhoneNumberValidator()


# Example usage function that could be integrated into your API
def validate_and_format_phone(phone_number: str) -> Optional[str]:
    """
    Simple function to validate and format a phone number.

    Usage:
        >>> validate_and_format_phone("+1 (555) 123-4567")
        '+1 5551234567'
    """
    result = phone_validator.validate_number(phone_number)
    if result.is_valid:
        return result.international_format
    return None

