"""Shared helpers (io, formatting, caching) used across tasks."""

import time
import functools
import hashlib
import json
from typing import Any, Callable, Dict, Optional, Tuple
from pathlib import Path


def _default_cache_path() -> Path:
    """Get default cache directory path."""
    cache_dir = Path.home() / ".cache" / "pytoolbox"
    cache_dir.mkdir(parents=True, exist_ok=True)
    return cache_dir


def _make_cache_key(func_name: str, args: Tuple, kwargs: Dict) -> str:
    """Create a unique cache key from function name and arguments."""
    key_data = {
        "func": func_name,
        "args": args,
        "kwargs": kwargs
    }
    key_str = json.dumps(key_data, sort_keys=True, default=str)
    return hashlib.sha256(key_str.encode()).hexdigest()


def cached_ttl(ttl: int = 300, use_disk: bool = False, persist: bool = False):
    """
    Decorator to cache function results with a time-to-live (TTL).

    Args:
        ttl: Time-to-live in seconds (default: 300 seconds / 5 minutes)
        use_disk: If True, cache to disk (persists across runs)
        persist: If use_disk=True, keep cache after TTL expires (for reuse)

    Returns:
        Decorated function with caching
    """
    cache: Dict[str, Tuple[float, Any]] = {}
    disk_cache_dir = _default_cache_path() if use_disk else None

    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Create cache key
            cache_key = _make_cache_key(func.__name__, args, kwargs)

            # Try memory cache first
            if cache_key in cache:
                timestamp, result = cache[cache_key]
                if time.time() - timestamp < ttl:
                    # Still fresh
                    return result
                else:
                    # Expired - remove from memory cache
                    if not persist:
                        del cache[cache_key]

            # Try disk cache if enabled
            if disk_cache_dir:
                disk_cache_file = disk_cache_dir / f"{cache_key}.json"
                if disk_cache_file.exists():
                    try:
                        with open(disk_cache_file, "r") as f:
                            disk_data = json.load(f)
                        if time.time() - disk_data["timestamp"] < ttl:
                            # Still fresh - load into memory cache
                            cache[cache_key] = (disk_data["timestamp"], disk_data["result"])
                            return disk_data["result"]
                        elif persist:
                            # Keep disk cache even if expired
                            disk_cache_file.unlink()
                    except (json.JSONDecodeError, KeyError, OSError):
                        pass

            # Call the actual function
            result = func(*args, **kwargs)

            # Store in memory cache
            timestamp = time.time()
            cache[cache_key] = (timestamp, result)

            # Store to disk if enabled
            if disk_cache_dir:
                try:
                    disk_cache_file = disk_cache_dir / f"{cache_key}.json"
                    with open(disk_cache_file, "w") as f:
                        json.dump({
                            "timestamp": timestamp,
                            "result": result
                        }, f, default=str)
                except (OSError, TypeError):
                    pass

            return result

        # Add cache management methods
        def clear_cache():
            """Clear all cached results for this function."""
            cache.clear()
            if disk_cache_dir:
                for cache_file in disk_cache_dir.glob(f"{func.__name__}_*.json"):
                    cache_file.unlink(missing_ok=True)

        wrapper.clear_cache = clear_cache  # type: ignore
        wrapper.get_cache_info = lambda: {  # type: ignore
            "size": len(cache),
            "cache_keys": list(cache.keys()),
            "disk": disk_cache_dir is not None
        }

        return wrapper
    return decorator


def cache_clear_all():
    """Clear all caches (memory and disk)."""
    # Clear disk cache directory
    cache_dir = _default_cache_path()
    if cache_dir.exists():
        for cache_file in cache_dir.iterdir():
            cache_file.unlink(missing_ok=True)
    print(f"Cleared cache directory: {cache_dir}")

