from functools import lru_cache
import time

def ttl_lru_cache(ttl_seconds, maxsize=128):
    """TTL cache built on top of lru_cache"""

    def decorator(func):
        cache = lru_cache(maxsize=maxsize)(func)
        cache._cache_timestamps = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            current_time = time.time()

            # Create a hashable key
            key = (args, frozenset(kwargs.items()) if kwargs else None)

            # Check if we have a timestamp for this key and if it's expired
            if key in cache._cache_timestamps:
                timestamp = cache._cache_timestamps[key]
                if current_time - timestamp >= ttl_seconds:
                    # Expired - remove from cache
                    cache.cache_clear()  # Simple approach: clear all
                    cache._cache_timestamps.clear()

            result = cache(*args, **kwargs)

            # Store timestamp (if not already stored)
            if key not in cache._cache_timestamps:
                cache._cache_timestamps[key] = current_time

            return result

        return wrapper

    return decorator

import time
from functools import lru_cache

def ttl_cache(ttl_seconds):
    def decorator(func):
        cache = {}

        @lru_cache(maxsize=128)
        def cached_func(*args, **kwargs):
            # Store the timestamp when this result was cached
            cache[(args, tuple(sorted(kwargs.items())))] = time.time()
            return func(*args, **kwargs)

        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            if key not in cache or time.time() - cache[key] > ttl_seconds:
                # Clear the cache and recompute
                cached_func.cache_clear()
                result = cached_func(*args, **kwargs)
                cache[key] = time.time()
                return result
            return cached_func(*args, **kwargs)

        wrapper.cache_info = cached_func.cache_info
        wrapper.cache_clear = cached_func.cache_clear
        return wrapper
    return decorator

