from typing import Optional

from .utils import get_env_value


def read_env_file(args) -> int:
    """
    Read a .env file and return one of its values.

    Usage:
        toolbox read-env <key> [--file .env] [--default value]
    """
    key = args['key']
    file_path = args.get('file', '.env')
    default = args.get('default')

    # Check if environment variable is already set
    if key in os.environ:
        print(os.environ[key])
        return 0

    value = get_env_value(file_path, key, default)

    if value:
        print(value)
        return 0
    else:
        print(f"Warning: Key '{key}' not found in '{file_path}'", file=sys.stderr)
        return 1


def get_task_handlers():
    """Register and return all task handlers."""
    return {
        'read-env': {
            'handler': read_env_file,
            'help': 'Read a value from a .env file',
            'args': [
                {
                    'name': 'key',
                    'help': 'The key to look up in the .env file',
                    'type': str
                },
                {
                    'name': '--file',
                    'help': 'Path to the .env file (default: .env)',
                    'type': str,
                    'default': '.env'
                },
                {
                    'name': '--default',
                    'help': 'Default value if key is not found',
                    'type': str,
                    'default': None
                }
            ]
        }
    }
